                checkpoint_path=checkpoint_path,
                optimizer=optimizer,
                prefix=prefix,
                **kwargs
            )

        if i is not None:
            return _pull(i)
        state = []
        for i in range(self.ensemble_size):
            state.append(_pull(i))
        return state

