                                         self.get(f'num_{cur_split}_data') %
                                         self.cfg.dataloader.batch_size))
        else:
            raise ValueError(f'Invalid mode {mode}.')

        return num_batch, num_batch_last_epoch, num_epoch, num_total_batch

