def _get_state(self):
    if _CKPT_BACKEND == "torchsnapshot":
        state = StateDict(
            collected_frames=self.collected_frames,
            _last_log=self._last_log,
            _last_save=self._last_save,
            _optim_count=self._optim_count,
        )
    else:
        state = OrderedDict(
            collected_frames=self.collected_frames,
